import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"16、【豫】 坤下震上","description":"周易口訣義 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"周易口訣義 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"classics/koujueyi/018.md","filePath":"classics/koujueyi/018.md"}'),r={name:"classics/koujueyi/018.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><p>彖曰：「豫」，剛應而志行，順以動，豫。豫順以動，故天地如之，而況「建侯行師」乎！天地以順動，故日月不過而四時不忒；聖人以順動，則刑罰清而民服。豫之時義大矣哉！</p><p>象曰：雷出地奮，「豫」。先王以作樂崇德，殷薦之上帝，以配祖考。</p><p>初六：鳴豫，兇。</p><p>象曰：「初六鳴豫」，志窮兇也。</p><p>六二：介於石，不終日，貞吉。</p><p>象曰：「不終日貞吉」，以中正也。</p><p>六三：盱豫，悔，遲有悔。</p><p>象曰：「盱豫」有「悔」，位不當也。</p><p>九四：由豫，大有得。勿疑，朋盍簪。</p><p>象曰：「由豫大有得」，志大行也。</p><p>六五：貞疾，恆不死。</p><p>象曰：「六五貞疾」，乘剛也。「恆不死」，中未亡也。</p><p>上六：冥豫成，有渝，無咎。</p><p>象曰：「冥豫」在上，何可長也。</p><p>無（四庫全書標明，摘錄時缺豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦）</p>',16)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
